package filo.scouter.config;

import lombok.Getter;

@Getter
public enum Layout
{
	L_3C2P(3, 2)
		{
			@Override
			public String toString()
			{
				return "3C2P";
			}
		},
	L_4C1P(4, 1)
		{
			@Override
			public String toString()
			{
				return "4C1P";
			}
		},
	L_4C2P(4, 2)
		{
			@Override
			public String toString()
			{
				return "4C2P";
			}
		};

	private final int maxCombat;
	private final int maxPuzzles;

	Layout(int combat, int puzzles)
	{
		this.maxCombat = combat;
		this.maxPuzzles = puzzles;
	}

	/**
	 * Return the accositated layout to your request
	 * @param combatQty The amount of Combat Rooms in the raid
	 * @param puzzleQty The amount of Puzzle Rooms in the raid
	 * @return That Layout or null
	 */
	public static Layout findLayout(int combatQty, int puzzleQty)
	{
		for (Layout layout : Layout.values())
		{
			if (layout.maxCombat == combatQty && layout.maxPuzzles == puzzleQty)
				return layout;
		}

		return null;
	}
}

package filo.scouter.data;

import net.runelite.client.util.Text;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public enum RoomEnum {
    COMBAT("muttadiles", "tekton", "vasa", "guardians", "shamans", "mystics", "vespula", "vanguards"),
    PUZZLE("crabs", "thieving", "tightrope", "ice demon");

    private final Set<String> roomNames;

    RoomEnum(String... roomNames) {
        this.roomNames = Arrays.stream(roomNames)
                .map(String::toLowerCase)
                .collect(Collectors.toSet());
    }

    /**
     * Returns roomtype based on String input
     * @param roomName name of room to check
     * @return RoomEnum.Combat | RoomEnum.Puzzle | Null if input is bad
     */
    public static RoomEnum fromRoomName(String roomName)
    {
        String roomNameLower = roomName.toLowerCase();
        for (RoomEnum roomEnum : values())
        {
            if (roomEnum.roomNames.contains(roomNameLower))
            {
                return roomEnum;
            }
        }

        return null;
    }

    /**
     * Could use this for blocked rooms, but I just want it to be careful with required rooms, as one letter would make scouting impossible.
     * @param userConfig string of room names separated by comma
     * @return a Set<String> of valid room names
     */
    public static Set<String> validateRequiredRooms(String userConfig)
    {
        Set<String> requiredSet = new HashSet<>();
        List<String> requiredRooms = Text.fromCSV(userConfig.toLowerCase());

        for (String roomName : requiredRooms)
        {
            if (isValidRoom(roomName))
            {
                requiredSet.add(roomName);
            }
        }

        return requiredSet;
    }

    public static boolean isValidRoom(String roomName)
    {
        for (RoomEnum roomEnum : values())
        {
            if (roomEnum.roomNames.contains(roomName))
            {
                return true;
            }
        }

        return false;
    }

    public static boolean hasPuzzleRoom(String roomNames)
    {
        for (String roomName : roomNames.split(","))
        {
            if (fromRoomName(roomName) == RoomEnum.PUZZLE)
            {
                return true;
            }
        }

        return false;
    }
}

package filo.scouter.data;

public enum PuzzleLayout
{
	// 3C2P
	FSCCSPCPSF("A", "C"),	//1
	SCPFCCSPSF("A", "C"),	//2
	SFCCSPCPSF("A", "C"),	//3
	SPSFPCCCSF("A", "C"),	//4
	SCSPFCCSPF("C", "C"),	//5

	// 4C1P
	SCPFCCCSSF("C"),	//1
	SCCFCPSCSF("A"),	//2
	SCFCPCSCFS("C"),	//3

	// 4C2P
	SCFPCCSPCF("C", "B"), 	//1
	SCFPCSCPCF("A", "B"),	//2
	SFCCPCSCPF("A", "B"),	//3
	SCFCPCCSPF("A", "C"),	//4
	SPCFCCSPCF("C", "C"),	//5
	FSCCPPCSCF("A", "C"),	//6
	SCFPCPCCSF("A", "B"),	//7
	FSCPCCSCPF("A", "B"),	//8
	SCFCPCSCPF("A", "A"),	//9
	SCPFCCSPCF("B", "C"),	//10
	SPCFCSCCPF("A", "C"),	//11
	SCPFCCCPSF("B", "B"),	//12
	FSPCCPSCCF("A", "A"), 	//13
	SCPFCPCSCF("B", "A"),	//14
	SCCFPCCSPF("A", "A");	//15

	private final String[] puzzleType = new String[2];

	PuzzleLayout(String... puzzleTypes)
	{
		for (int i = 0; i < puzzleTypes.length; i++)
		{
			puzzleType[i] = puzzleTypes[i];
		}
	}

	public static PuzzleLayout getByLayout(String raidLayout)
	{
		for (PuzzleLayout layout : PuzzleLayout.values())
		{
			if (layout.name().equalsIgnoreCase(raidLayout))
				return layout;
		}

		return null;	// Only if I don't support the layout (5c2p / 5c3p)
	}

	public String getPuzzleType(int puzzleIndex)
	{
		return puzzleIndex > puzzleType.length || puzzleIndex == -1 ? "N/a" : puzzleType[puzzleIndex];
	}
}

package filo.scouter;

import filo.scouter.config.Crabs;
import filo.scouter.config.IncludeMode;
import filo.scouter.config.Layout;
import filo.scouter.config.Overload;
import filo.scouter.config.OverloadPosition;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import java.util.Collections;
import java.util.Set;

@ConfigGroup("coxscoutingqol")
public interface ScoutHelperConfig extends Config
{
	@ConfigSection(
		name = "Overload Settings",
		description = "Configure your overload preferences",
		position = 4,
		closedByDefault = true
	)
	String overloadSection = "Overload Section";

	@ConfigSection(
		name = "Room Settings",
		description = "Settings for Rooms",
		position = 3,
		closedByDefault = true
	)
	String raidSection = "Raid Section";

	@ConfigSection(
		name = "Rotation Settings",
		description = "Filter Rotations",
		position = 2,
		closedByDefault = true
	)
	String rotationSection = "Rotation Section";

	@ConfigSection(
		name = "Layout Settings",
		description = "Filter Layouts (Combat : Puzzle Ratios)",
		position = 1,
		closedByDefault = true
	)
	String layoutSection = "Layout Section";

	@ConfigSection(
		name = "General Settings",
		description = "General Settings",
		position = 0
	)
	String generalSection = "General Settings";

	@ConfigItem(
			keyName = "notifyRaid",
			name = "Notify on Raid",
			description = "Send a notification when a raid is scouted",
			section = generalSection,
			position = 0
	)
	default Notification notifyRaid()
	{
		return Notification.ON;
